package profile

import (
	"strings"

	"github.com/roachadam/mimicry/internal/weburl"
)

// URLs is how a browser's URL parser differs from the others measured:
// what every one does (the URL standard's host, path and query forms, as
// the urls capture measures them) is mimicry's, not a profile's.
// Generated by internal/harness/cmd/kindsgen from the urls capture; not
// hand-edited.
type URLs struct {
	// PathEncodes are the characters the browser percent-encodes in a
	// path beyond the set every browser measured does: "|" (Chrome).
	PathEncodes string `json:"pathEncodes,omitempty"`
	// CheckPunycode: an ASCII host goes through UTS #46 ToASCII as a
	// non-ASCII one does, so an "xn--" label that is not valid punycode
	// makes the URL invalid (Firefox, as the URL standard says). Without
	// it an ASCII host is only lowercased: such a label is sent as
	// written (Chrome, Safari).
	CheckPunycode bool `json:"checkPunycode,omitempty"`
}

func (c *checker) checkURLs(u *URLs) {
	if u == nil {
		return
	}

	for i := range len(u.PathEncodes) {
		ch := u.PathEncodes[i]

		switch {
		case ch <= ' ' || ch > '~':
			c.add("urls.pathEncodes", "%q is not a printable ASCII character", string(ch))
		case ch == '%' || ch == '/' || ch == '\\':
			c.add("urls.pathEncodes", "%q is never encoded in a path", string(ch))
		case weburl.InPathSet(ch):
			c.add("urls.pathEncodes", "%q is in the set every browser encodes already", string(ch))
		case strings.IndexByte(u.PathEncodes[:i], ch) >= 0:
			c.add("urls.pathEncodes", "%q appears twice", string(ch))
		}
	}
}
